  const requestedTaxText = formatCurrencyGroups(requestedTaxes);
  const averageDiscount = currentUsd > 0 ? ((currentUsd - requestedUsd) / currentUsd) * 100 : 0;
  const setInvoiceText = (selector, value) => { const node = document.querySelector(selector); if (node) node.textContent = value; };
  const setInvoiceHtml = (selector, value) => { const node = document.querySelector(selector); if (node) node.innerHTML = value; };
  setInvoiceText("#invoiceCurrentSubtotal", currentTotalText);
